export default Profile;

import React, { useMemo } from 'react';
import { MOCK_PRODUCTS } from '../constants';
import { MapPin } from 'lucide-react';

const MapPage: React.FC = () => {
  // We will simulate a map by plotting points on a relative coordinate system container
  // In a real app, this would use Google Maps or Leaflet.
  // For the demo and restrictions, we use a stylized CSS/SVG representation.

  const allProducts = useMemo(() => {
     const stored = localStorage.getItem('products');
     return stored ? [...MOCK_PRODUCTS, ...JSON.parse(stored)] : MOCK_PRODUCTS;
  }, []);

  // Simple projection function for China-ish coordinates (Rough approximation for demo visuals)
  // Lat: 18 (South) - 54 (North). Lng: 73 (West) - 135 (East)
  const getPosition = (lat: number, lng: number) => {
    const minLat = 18;
    const maxLat = 54;
    const minLng = 73;
    const maxLng = 135;

    const y = 100 - ((lat - minLat) / (maxLat - minLat)) * 100;
    const x = ((lng - minLng) / (maxLng - minLng)) * 100;

    // Clamp values
    return { 
        top: `${Math.max(10, Math.min(90, y))}%`, 
        left: `${Math.max(10, Math.min(90, x))}%` 
    };
  };

  return (
    <div className="h-full flex flex-col bg-slate-50">
      <header className="px-4 py-4 bg-white border-b border-slate-200">
        <h1 className="text-lg font-bold text-slate-800">特产地图探索</h1>
        <p className="text-xs text-slate-500">发现全国各地的宝藏好物</p>
      </header>

      <div className="flex-1 relative overflow-hidden bg-sky-50">
        {/* Background Map Graphic (Abstract SVG) */}
        <div className="absolute inset-0 p-8 flex items-center justify-center opacity-20 pointer-events-none">
            <svg viewBox="0 0 800 600" className="w-full h-full text-slate-300 fill-current">
                {/* Simplified Abstract China Shape */}
                <path d="M 200,400 L 300,500 L 500,500 L 600,400 L 700,300 L 600,100 L 400,50 L 200,100 L 100,250 Z" />
            </svg>
        </div>

        {/* Map Grid Lines for visual effect */}
        <div className="absolute inset-0" style={{
            backgroundImage: 'radial-gradient(#cbd5e1 1px, transparent 1px)',
            backgroundSize: '20px 20px',
            opacity: 0.5
        }}></div>

        {/* Product Pins */}
        <div className="absolute inset-4 sm:inset-10 md:inset-20 bg-white/40 backdrop-blur-sm rounded-3xl border border-white/50 shadow-xl overflow-hidden relative">
            <div className="absolute inset-0 w-full h-full">
                {allProducts.map((product, idx) => {
                    const pos = getPosition(product.location.lat, product.location.lng);
                    return (
                        <div 
                            key={product.id + idx}
                            className="absolute transform -translate-x-1/2 -translate-y-1/2 group cursor-pointer z-10 hover:z-50"
                            style={{ top: pos.top, left: pos.left }}
                        >
                            <div className="relative flex flex-col items-center">
                                {/* Tooltip */}
                                <div className="absolute bottom-full mb-2 hidden group-hover:block w-32 bg-white p-2 rounded-lg shadow-xl text-center z-50">
                                    <div className="w-full h-20 rounded-md overflow-hidden mb-1">
                                        <img src={product.imageUrl} className="w-full h-full object-cover" alt="" />
                                    </div>
                                    <div className="text-xs font-bold text-slate-800 truncate">{product.title}</div>
                                    <div className="text-[10px] text-orange-600">{product.location.name}</div>
                                    {/* Arrow */}
                                    <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-white"></div>
                                </div>

                                {/* Pin Icon */}
                                <div className="relative">
                                    <div className="w-8 h-8 rounded-full bg-orange-100 border-2 border-orange-500 flex items-center justify-center shadow-lg group-hover:scale-125 transition-transform duration-200">
                                        <img 
                                            src={product.imageUrl} 
                                            alt="mini" 
                                            className="w-full h-full rounded-full object-cover opacity-80"
                                        />
                                    </div>
                                    <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-orange-500 rounded-full animate-ping"></div>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Legend */}
            <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur px-3 py-2 rounded-lg shadow-sm text-xs border border-slate-100">
                <div className="flex items-center gap-2 mb-1">
                    <div className="w-2 h-2 rounded-full bg-orange-500"></div>
                    <span className="text-slate-600">食品</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-purple-500"></div>
                    <span className="text-slate-600">手工艺</span>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

